45	    }
46	    uint64_t roundingTruncLen = 64;
47	    uint64_t mask0 = (truncLen >= roundingTruncLen) ? 0 : 0x1ul << truncLen;
48	    uint64_t mask1 = (truncLen > roundingTruncLen) ? 0 : 0x1ul << (truncLen - 1);
49	    uint64_t mask2 = mask1 - 1;
50	
51	    bool lastBit = ((man & mask0) > 0);      // Last bit after conversion
52	    bool truncHighBit = ((man & mask1) > 0); // Highest bit in the truncated part
53	    bool truncLeft = ((man & mask2) > 0);    // Truncated left part (except for the highest bit)
54	
55	    return (truncHighBit && (truncLeft || lastBit));
56	}
