11	/*!
12	 * \file kernel_fp16.cpp
13	 * \brief
14	 */
15	#include "kernel_fp16.h"
16	
17	namespace {
18	constexpr uint16_t K_MAN_BIT_LENGTH = 11;
19	constexpr int16_t HFEXP_NUM = 31;
20	constexpr uint32_t ERET_NUM = 255;
21	} // namespace
22	
23	// namespace float16 {
24	/**
25	 * @ingroup half global filed
26	 * @brief   round mode of last valid digital
27	 */
28	const enum TagFp16RoundMode ROUND_MODE = TagFp16RoundMode::K_ROUND_TO_NEAREST;
29	
30	void ExtractFp16(const uint16_t& val, uint16_t& s, int16_t& e, uint16_t& m)
31	{
32	    // 1.Extract
33	    s = FP16_EXTRAC_SIGN(val);
34	    e = FP16_EXTRAC_EXP(val);
35	    m = FP16_EXTRAC_MAN(val);
36	    // Denormal
37	    if (e == 0) {
38	        e = 1;
39	    }
40	}
41	
42	/**
43	 * @ingroup half static method
44	 * @param [in] man       truncated mantissa
45	 * @param [in] shiftOut left shift bits based on ten bits
46	 * @brief   judge whether to add one to the result while converting half to
47	 * other datatype
48	 * @return  Return true if add one, otherwise false
49	 */
50	static bool IsRoundOne(uint64_t man, uint16_t truncLen)
51	{
52	    uint64_t mask0 = 0x4;
53	    uint64_t mask1 = 0x2;
54	    uint64_t mask2;
55	    uint16_t shiftOut = static_cast<uint16_t>(truncLen - static_cast<uint16_t>(DimIndex::K_DIM2));
56	    mask0 = mask0 << shiftOut;
57	    mask1 = mask1 << shiftOut;
58	    mask2 = mask1 - 1;
59	
60	    bool lastBit = ((man & mask0) > 0);
61	    bool truncHigh = false;
62	    bool truncLeft = false;
63	    if (ROUND_MODE == TagFp16RoundMode::K_ROUND_TO_NEAREST) {
64	        truncHigh = ((man & mask1) > 0);
65	        truncLeft = ((man & mask2) > 0);
66	    }
67	    return (truncHigh && (truncLeft || lastBit));
68	}
69	
70	/**
71	 * @ingroup half public method
72	 * @param [in] exp       exponent of half value
73	 * @param [in] man       exponent of half value
74	 * @brief   normalize half value
75	 * @return
76	 */
77	static void Fp16Normalize(int16_t& exp, uint16_t& man)
78	{
79	    // set to invalid data
80	    if (exp >= static_cast<int16_t>(Fp16BasicParam::K_FP16_MAX_EXP)) {
81	        exp = static_cast<int16_t>(Fp16BasicParam::K_FP16_MAX_EXP);
82	        man = static_cast<uint16_t>(Fp16BasicParam::K_FP16_MAX_MAN);
83	    } else if ((exp == 0) && (man == static_cast<uint16_t>(Fp16BasicParam::K_FP16_MAN_HIDE_BIT))) {
84	        exp++;
85	        man = 0;
86	    }
87	}
88	
89	/**
90	 * @ingroup half math conversion static method
91	 * @param [in] fpVal uint16_t value of half object
92	 * @brief   Convert half to float/fp32
93	 * @return  Return float/fp32 value of fpVal which is the value of half object
94	 */
95	static float Fp16ToFloat(const uint16_t& fpVal)
96	{
97	    uint16_t hfSign;
98	    uint16_t hfMan;
99	    int16_t hfExp;
100	    ExtractFp16(fpVal, hfSign, hfExp, hfMan);
101	
102	    while ((hfMan != 0) && ((hfMan & static_cast<uint16_t>(Fp16BasicParam::K_FP16_MAN_HIDE_BIT)) == 0)) {
103	        hfMan <<= 1;
104	        hfExp--;
105	    }
106	
107	    uint32_t eRet;
108	    uint32_t mRet;
109	    uint32_t sRet = hfSign;
110	
111	    if (hfExp == HFEXP_NUM) {
112	        eRet = ERET_NUM;
113	        mRet = hfMan
114	               << (static_cast<uint32_t>(Fp32BasicParam::K_FP32_MAN_LEN) -
115	                   static_cast<uint32_t>(Fp16BasicParam::K_FP16_MAN_LEN));
116	        uint32_t fVal = FP32_CONSTRUCTOR(sRet, eRet, mRet);
117	        auto pRetV = reinterpret_cast<float*>(&fVal);
118	
119	        return *pRetV;
120	    }
121	
122	    if (hfMan == 0) {
123	        eRet = 0;
124	        mRet = 0;
125	    } else {
126	        eRet = (static_cast<uint32_t>(hfExp) - static_cast<uint32_t>(Fp16BasicParam::K_FP16_EXP_BIAS)) +
127	               static_cast<uint32_t>(Fp32BasicParam::K_FP32_EXP_BIAS);
128	        mRet = static_cast<uint32_t>(hfMan & static_cast<uint16_t>(Fp16BasicParam::K_FP16_MAN_MASK));
129	        mRet = mRet
130	               << (static_cast<uint32_t>(Fp32BasicParam::K_FP32_MAN_LEN) -
131	                   static_cast<uint32_t>(Fp16BasicParam::K_FP16_MAN_LEN));
132	    }
133	    uint32_t fVal = FP32_CONSTRUCTOR(sRet, eRet, mRet);
134	    auto pRetV = reinterpret_cast<float*>(&fVal);
135	
136	    return *pRetV;
137	}
138	
139	/**
140	 * @ingroup half math conversion static method
141	 * @param [in] fpVal uint16_t value of half object
142	 * @brief   Convert half to double/fp64
143	 * @return  Return double/fp64 value of fpVal which is the value of half object
144	 */
145	static double Fp16ToDouble(const uint16_t& fpVal)
146	{
147	    uint16_t hfSign;
148	    uint16_t hfMan;
149	    int16_t hfExp;
150	    ExtractFp16(fpVal, hfSign, hfExp, hfMan);
151	
152	    while ((hfMan != 0) && ((hfMan & static_cast<uint16_t>(Fp16BasicParam::K_FP16_MAN_HIDE_BIT)) == 0)) {
153	        hfMan <<= 1;
154	        hfExp--;
155	    }
156	
157	    uint64_t eRet;
158	    uint64_t mRet;
159	    if (hfMan == 0) {
160	        eRet = 0;
161	        mRet = 0;
162	    } else {
163	        eRet = (static_cast<uint64_t>(hfExp) - static_cast<uint64_t>(Fp16BasicParam::K_FP16_EXP_BIAS)) +
164	               static_cast<uint64_t>(Fp64BasicParam::K_FP64_EXP_BIAS);
165	        mRet = hfMan & static_cast<uint64_t>(Fp16BasicParam::K_FP16_MAN_MASK);
166	        mRet = mRet
167	               << (static_cast<uint64_t>(Fp64BasicParam::K_FP64_MAN_LEN) -
168	                   static_cast<uint64_t>(Fp16BasicParam::K_FP16_MAN_LEN));
169	    }
170	    uint64_t fVal = (static_cast<uint64_t>(hfSign) << static_cast<uint64_t>(Fp64BasicParam::K_FP64_SIGN_INDEX)) |
171	                    (eRet << static_cast<uint64_t>(Fp64BasicParam::K_FP64_MAN_LEN)) | (mRet);
172	    auto pRetV = reinterpret_cast<double*>(&fVal);
173	
174	    return *pRetV;
175	}
176	
177	// / @ingroup half static method
178	// / @param [in] sRet       sign of half value
179	// / @param [in] longIntM   man uint64_t value of half object
180	// / @param [in] shiftOut   shift offset
181	// / @brief   calculate uint8 value by sign,man and shift offset
182	// / @return Return uint8 value of half object
183	static uint8_t GetUint8ValByMan(uint8_t sRet, const uint64_t& longIntM, const uint16_t& shiftOut)
184	{
185	    bool needRound = IsRoundOne(longIntM, shiftOut + static_cast<uint16_t>(Fp16BasicParam::K_FP16_MAN_LEN));
186	    auto mRet = static_cast<uint8_t>(
187	        (longIntM >> (static_cast<uint32_t>(Fp16BasicParam::K_FP16_MAN_LEN) + static_cast<uint32_t>(shiftOut))) &
188	        static_cast<uint8_t>(NumBitMax::K_BIT_LEN8_MAX));
189	    needRound = needRound && (((sRet == 0) && (mRet < static_cast<uint8_t>(NumBitMax::K_INT8_MAX))) ||
190	                              ((sRet == 1) && (mRet <= static_cast<uint8_t>(NumBitMax::K_INT8_MAX))));
191	    if (needRound) {
192	        mRet++;
193	    }
194	    if (sRet != 0) {
195	        mRet = (~mRet) + 1;
196	    }
197	    if (mRet == 0) {
198	        sRet = 0;
199	    }
200	    return static_cast<uint8_t>((sRet << static_cast<uint16_t>(BitShift::K_BIT_SHIFT7)) | (mRet));
201	}
202	
203	static void CalcOverflowFlagInt8(
204	    const uint8_t& sRet, uint16_t& hfE, uint64_t& longIntM, uint8_t& overflowFlag, uint16_t& shiftOut)
205	{
206	    while (hfE != static_cast<uint16_t>(Fp16BasicParam::K_FP16_EXP_BIAS)) {
207	        if (hfE > static_cast<uint16_t>(Fp16BasicParam::K_FP16_EXP_BIAS)) {
208	            hfE--;
209	            longIntM = longIntM << 1;
210	            if ((sRet == 1) && (longIntM >= 0x20000u)) { // sign=1,negative number(<0)
211	                longIntM = 0x20000u;                     // 10 0000 0000 0000 0000  10(half-man)+7(int8)=17bit
212	                overflowFlag = 1;
213	                break;
214	            } else if ((sRet != 1) && (longIntM >= 0x1FFFFu)) { // sign=0,positive number(>0)
215	                longIntM = 0x1FFFFu;                            // 01 1111 1111 1111 1111  10(half-man)+7(int8)
216	                overflowFlag = 1;
217	                break;
218	            }
219	        } else {
220	            hfE++;
221	            shiftOut++;
222	        }
223	    }
224	}
225	
226	/**
227	 * @ingroup half math conversion static method
228	 * @param [in] fpVal uint16_t value of half object
229	 * @brief   Convert half to int8_t
230	 * @return  Return int8_t value of fpVal which is the value of half object
231	 */
232	static int8_t Fp16ToInt8(const uint16_t& fpVal)
233	{
234	    uint8_t ret;
235	    // 1.get sRet and shift it to bit0.
236	    uint8_t sRet = static_cast<uint8_t>(FP16_EXTRAC_SIGN(fpVal));
237	    // 2.get hfE and hfM
238	    uint16_t hfE = static_cast<uint16_t>(FP16_EXTRAC_EXP(fpVal));
239	    uint16_t hfM = FP16_EXTRAC_MAN(fpVal);
240	
241	    if (FP16_IS_DENORM(fpVal)) { // Denormalized number
242	        return 0;
243	    }
244	
245	    uint64_t longIntM = hfM;
246	    uint8_t overflowFlag = 0;
247	    uint16_t shiftOut = 0;
248	    if (FP16_IS_INVALID(fpVal)) { // Inf or NaN
249	        overflowFlag = 1;
250	    } else {
251	        CalcOverflowFlagInt8(sRet, hfE, longIntM, overflowFlag, shiftOut);
252	    }
253	    if (overflowFlag != 0) {
254	        ret = static_cast<uint8_t>(NumBitMax::K_INT8_MAX) + sRet;
255	    } else {
256	        // Generate final result
257	        ret = GetUint8ValByMan(sRet, longIntM, shiftOut);
258	    }
259	
260	    return static_cast<int8_t>(ret);
261	}
262	
263	static void CalcOverflowFlagUInt8(
264	    uint16_t& hfE, uint64_t& longIntM, uint8_t& overflowFlag, uint8_t& mRet, uint16_t& shiftOut)
265	{
266	    while (hfE != static_cast<uint16_t>(Fp16BasicParam::K_FP16_EXP_BIAS)) {
267	        if (hfE > static_cast<uint16_t>(Fp16BasicParam::K_FP16_EXP_BIAS)) {
268	            hfE--;
269	            longIntM = longIntM << 1;
270	            if (longIntM >= 0x40000Lu) { // overflow 0100 0000 0000 0000 0000
271	                longIntM = 0x3FFFFLu;    // 11 1111 1111 1111 1111   10(half-man)+8(uint8)=18bit
272	                overflowFlag = 1;
273	                mRet = ~0;
274	                break;
275	            }
276	        } else {
277	            hfE++;
278	            shiftOut++;
279	        }
280	    }
281	}
282	
283	/**
284	 * @ingroup half math conversion static method
285	 * @param [in] fpVal uint16_t value of half object
286	 * @brief   Convert half to uint8_t
287	 * @return  Return uint8_t value of fpVal which is the value of half object
288	 */
289	static uint8_t Fp16ToUInt8(const uint16_t& fpVal)
290	{
291	    uint8_t mRet = 0;
292	    // 1.get sRet and shift it to bit0.
293	    uint16_t sRet = FP16_EXTRAC_SIGN(fpVal);
294	    // 2.get hfE and hfM
295	    uint16_t hfE = static_cast<uint16_t>(FP16_EXTRAC_EXP(fpVal));
296	    uint16_t hfM = FP16_EXTRAC_MAN(fpVal);
297	
298	    if (FP16_IS_DENORM(fpVal)) { // Denormalized number
299	        return 0;
300	    }
301	
302	    if (FP16_IS_INVALID(fpVal)) { // Inf or NaN
303	        mRet = ~0;
304	    } else {
305	        uint64_t longIntM = hfM;
306	        uint8_t overflowFlag = 0;
307	        uint16_t shiftOut = 0;
308	        CalcOverflowFlagUInt8(hfE, longIntM, overflowFlag, mRet, shiftOut);
309	        if (overflowFlag == 0) {
310	            bool needRound = IsRoundOne(longIntM, shiftOut + static_cast<uint16_t>(Fp16BasicParam::K_FP16_MAN_LEN));
311	            mRet = static_cast<uint8_t>(
312	                (longIntM >>
313	                 (static_cast<uint32_t>(Fp16BasicParam::K_FP16_MAN_LEN) + static_cast<uint32_t>(shiftOut))) &
314	                static_cast<uint8_t>(NumBitMax::K_BIT_LEN8_MAX));
315	            if (needRound && (mRet != static_cast<uint8_t>(NumBitMax::K_BIT_LEN8_MAX))) {
316	                mRet++;
317	            }
318	        }
319	    }
320	
321	    if (sRet == 1) { // Negative number
322	        mRet = 0;
323	    }
324	    // mRet equal to final result
325	    return mRet;
326	}
327	// / @ingroup half static method
328	// / @param [in] sRet       sign of half value
329	// / @param [in] longIntM   man uint64_t value of half object
330	// / @param [in] shiftOut   shift offset
331	// / @brief   calculate uint16 value by sign,man and shift offset
332	// / @return Return uint16 value of half object
333	static uint16_t GetUint16ValByMan(uint16_t sRet, const uint64_t& longIntM, const uint16_t& shiftOut)
334	{
335	    bool needRound = IsRoundOne(longIntM, shiftOut + static_cast<uint16_t>(Fp16BasicParam::K_FP16_MAN_LEN));
336	    auto mRet = static_cast<uint16_t>(
337	        (longIntM >> (static_cast<uint32_t>(Fp16BasicParam::K_FP16_MAN_LEN) + static_cast<uint32_t>(shiftOut))) &
338	        static_cast<uint16_t>(NumBitMax::K_BIT_LEN16_MAX));
339	    if (needRound && (mRet < static_cast<int16_t>(NumBitMax::K_INT16_MAX))) {
340	        mRet++;
341	    }
342	    if (sRet != 0) {
343	        mRet = (~mRet) + 1;
344	    }
345	    if (mRet == 0) {
346	        sRet = 0;
347	    }
348	    return static_cast<uint16_t>((sRet << static_cast<uint16_t>(BitShift::K_BIT_SHIFT15)) | (mRet));
349	}
