351	static void CalcOverflowFlagInt16(
352	    uint16_t& hfE, uint64_t& longIntM, const uint16_t& sRet, uint8_t& overflowFlag, uint16_t& shiftOut)
353	{
354	    while (hfE != static_cast<uint16_t>(Fp16BasicParam::K_FP16_EXP_BIAS)) {
355	        if (hfE > static_cast<uint16_t>(Fp16BasicParam::K_FP16_EXP_BIAS)) {
356	            longIntM = longIntM << 1;
357	            hfE--;
358	            if ((sRet == 1) && (longIntM > 0x2000000Lu)) { // sign=1,negative number(<0)
359	                longIntM = 0x2000000Lu;                    // 10(half-man)+15(int16)=25bit
360	                overflowFlag = 1;
361	                break;
362	            } else if ((sRet != 1) && (longIntM >= 0x1FFFFFFLu)) { // sign=0,positive number(>0) Overflow
363	                longIntM = 0x1FFFFFFLu;                            // 10(half-man)+15(int16)=25bit
364	                overflowFlag = 1;
365	                break;
366	            }
367	        } else {
368	            shiftOut++;
369	            hfE++;
370	        }
371	    }
372	}
