378	 */
379	static int16_t Fp16ToInt16(const uint16_t& fpVal)
380	{
381	    int16_t ret;
382	    uint16_t retV;
383	    // 1.get sRet and shift it to bit0.
384	    uint16_t sRet = FP16_EXTRAC_SIGN(fpVal);
385	    // 2.get hfE and hfM
386	    uint16_t hfM = FP16_EXTRAC_MAN(fpVal);
387	    uint16_t hfE = static_cast<uint16_t>(FP16_EXTRAC_EXP(fpVal));
388	
389	    if (FP16_IS_DENORM(fpVal)) { // Denormalized number
390	        retV = 0;
391	        ret = *(reinterpret_cast<uint8_t*>(&retV));
392	        return ret;
393	    }
394	
395	    uint8_t overflowFlag = 0;
396	    uint16_t shiftOut = 0;
397	    uint64_t longIntM = hfM;
398	    if (FP16_IS_INVALID(fpVal)) { // Inf or NaN
399	        overflowFlag = 1;
400	    } else {
401	        CalcOverflowFlagInt16(hfE, longIntM, sRet, overflowFlag, shiftOut);
402	    }
403	    if (overflowFlag != 0) {
404	        retV = static_cast<int16_t>(NumBitMax::K_INT16_MAX) + sRet;
405	    } else {
406	        // Generate final result
407	        retV = GetUint16ValByMan(sRet, longIntM, shiftOut);
408	    }
409	    ret = *(reinterpret_cast<int16_t*>(&retV));
410	    return ret;
411	}
