418	 */
419	static uint16_t Fp16ToUInt16(const uint16_t& fpVal)
420	{
421	    uint16_t mRet;
422	    // 1.get sRet and shift it to bit0.
423	    uint16_t sRet = FP16_EXTRAC_SIGN(fpVal);
424	    // 2.get hfE and hfM
425	    int16_t hfE = FP16_EXTRAC_EXP(fpVal);
426	    uint16_t hfM = FP16_EXTRAC_MAN(fpVal);
427	
428	    if (FP16_IS_DENORM(fpVal)) { // Denormalized number
429	        return 0;
430	    }
431	
432	    if (FP16_IS_INVALID(fpVal)) { // Inf or NaN
433	        mRet = ~0;
434	    } else {
435	        uint16_t shiftOut = 0;
436	        uint64_t longIntM = hfM;
437	        while (hfE != static_cast<int16_t>(Fp16BasicParam::K_FP16_EXP_BIAS)) {
438	            if (hfE > static_cast<int16_t>(Fp16BasicParam::K_FP16_EXP_BIAS)) {
439	                hfE--;
440	                longIntM = longIntM << 1;
441	            } else {
442	                shiftOut++;
443	                hfE++;
444	            }
445	        }
446	        bool needRound = IsRoundOne(longIntM, shiftOut + static_cast<uint16_t>(Fp16BasicParam::K_FP16_MAN_LEN));
447	        mRet = static_cast<uint16_t>(
448	            (longIntM >> (static_cast<uint32_t>(Fp16BasicParam::K_FP16_MAN_LEN) + static_cast<uint32_t>(shiftOut))) &
449	            static_cast<uint16_t>(NumBitMax::K_BIT_LEN16_MAX));
450	        if (needRound && (mRet != static_cast<uint16_t>(NumBitMax::K_BIT_LEN16_MAX))) {
451	            mRet++;
452	        }
453	    }
454	
455	    if (sRet == 1) { // Negative number
456	        mRet = 0;
457	    }
458	    // mRet equal to final result
459	    return mRet;
460	}
