562	static uint16_t Fp16AddCalVal(const uint16_t& sRet, int16_t eRet, uint16_t mRet, uint32_t mTrunc, uint16_t shiftOut)
563	{
564	    uint16_t mMin = static_cast<uint16_t>(Fp16BasicParam::K_FP16_MAN_HIDE_BIT) << shiftOut;
565	    uint16_t mMax = mMin << 1;
566	    // Denormal
567	    while ((mRet < mMin) && (eRet > 0)) { // the value of mRet should not be smaller than 2^23
568	        mRet = mRet << 1;
569	        mRet += (static_cast<uint32_t>(Fp32BasicParam::K_FP32_SIGN_MASK) & mTrunc) >>
570	                static_cast<uint16_t>(Fp32BasicParam::K_FP32_SIGN_INDEX);
571	        mTrunc = mTrunc << 1;
572	        eRet = eRet - 1;
573	    }
574	    while (mRet >= mMax) { // the value of mRet should be smaller than 2^24
575	        mTrunc = mTrunc >> 1;
576	        mTrunc = mTrunc | (static_cast<uint32_t>(Fp32BasicParam::K_FP32_SIGN_MASK) * (mRet & 1));
577	        mRet = mRet >> 1;
578	        eRet = eRet + 1;
579	    }
580	
581	    bool bLastBit = ((mRet & 1) > 0);
582	    bool bTruncHigh = (ROUND_MODE == TagFp16RoundMode::K_ROUND_TO_NEAREST) &&
583	                      ((mTrunc & static_cast<uint32_t>(Fp32BasicParam::K_FP32_SIGN_MASK)) > 0);
584	    bool bTruncLeft = (ROUND_MODE == TagFp16RoundMode::K_ROUND_TO_NEAREST) &&
585	                      ((mTrunc & static_cast<uint32_t>(Fp32BasicParam::K_FP32_ABS_MAX)) > 0);
586	    mRet = ManRoundToNearest(bLastBit, bTruncHigh, bTruncLeft, mRet, shiftOut);
587	    while (mRet >= mMax) {
588	        mRet = mRet >> 1;
589	        eRet = eRet + 1;
590	    }
591	
592	    if ((eRet == 0) && (mRet <= mMax)) {
593	        mRet = mRet >> 1;
594	    }
595	    Fp16Normalize(eRet, mRet);
596	    uint16_t ret = FP16_CONSTRUCTOR(sRet, static_cast<uint16_t>(eRet), mRet);
597	    return ret;
598	}
