600	/**
601	 * @ingroup half math operator
602	 * @param [in] v1 left operator value of half object
603	 * @param [in] v2 right operator value of half object
604	 * @brief   Performing half addition
605	 * @return  Return half result of adding this and fp
606	 */
607	static uint16_t Fp16Add(uint16_t v1, uint16_t v2)
608	{
609	    uint16_t sa;
610	    uint16_t sb;
611	    int16_t ea;
612	    int16_t eb;
613	    uint32_t ma;
614	    uint32_t mb;
615	    uint16_t maTmp;
616	    uint16_t mbTmp;
617	    uint16_t shiftOut = 0;
618	    // 1.Extract
619	    ExtractFp16(v1, sa, ea, maTmp);
620	    ExtractFp16(v2, sb, eb, mbTmp);
621	    ma = maTmp;
622	    mb = mbTmp;
623	
624	    uint16_t sum;
625	    uint16_t sRet;
626	    if (sa != sb) {
627	        ReverseMan(sa > 0, ma);
628	        ReverseMan(sb > 0, mb);
629	        sum = static_cast<uint16_t>(GetManSum(ea, ma, eb, mb));
630	        sRet = (sum & static_cast<uint16_t>(Fp16BasicParam::K_FP16_SIGN_MASK)) >>
631	               static_cast<uint16_t>(Fp16BasicParam::K_FP16_SIGN_INDEX);
632	        ReverseMan(sRet > 0, ma);
633	        ReverseMan(sRet > 0, mb);
634	    } else {
635	        sum = static_cast<uint16_t>(GetManSum(ea, ma, eb, mb));
636	        sRet = sa;
637	    }
638	
639	    if (sum == 0) {
640	        shiftOut = 3; // shift to left 3 bits
641	        ma = ma << shiftOut;
642	        mb = mb << shiftOut;
643	    }
644	
645	    uint32_t mTrunc = 0;
646	    int16_t eRet = std::max(ea, eb);
647	    uint32_t eTmp = static_cast<uint32_t>(std::abs(ea - eb));
648	    if (ea > eb) {
649	        mTrunc = (mb << (static_cast<uint32_t>(BitShift::K_BIT_SHIFT32) - eTmp));
650	        mb = RightShift(mb, eTmp);
651	    } else if (ea < eb) {
652	        mTrunc = (ma << (static_cast<uint32_t>(BitShift::K_BIT_SHIFT32) - eTmp));
653	        ma = RightShift(ma, eTmp);
654	    }
655	    // calculate mantissav
656	    auto mRet = static_cast<uint16_t>(ma + mb);
657	    return Fp16AddCalVal(sRet, eRet, mRet, mTrunc, shiftOut);
658	}
