660	/**
661	 * @ingroup half math operator
662	 * @param [in] v1 left operator value of half object
663	 * @param [in] v2 right operator value of half object
664	 * @brief   Performing half subtraction
665	 * @return  Return half result of subtraction fp from this
666	 */
667	static uint16_t Fp16Sub(uint16_t v1, uint16_t v2)
668	{
669	    // Reverse
670	    uint16_t tmp = ((~(v2)) & static_cast<uint16_t>(Fp16BasicParam::K_FP16_SIGN_MASK)) |
671	                   (v2 & static_cast<uint16_t>(Fp16BasicParam::K_FP16_ABS_MAX));
672	    return Fp16Add(v1, tmp);
673	}
674	/**
675	 * @ingroup half math operator
676	 * @param [in] v1 left operator value of half object
677	 * @param [in] v2 right operator value of half object
678	 * @brief   Performing half multiplication
679	 * @return  Return half result of multiplying this and fp
680	 */
681	static uint16_t Fp16Mul(uint16_t v1, uint16_t v2)
682	{
683	    uint16_t sa;
684	    uint16_t sb;
685	    int16_t ea;
686	    int16_t eb;
687	    uint16_t mRet;
688	    uint16_t maTmp;
689	    uint16_t mbTmp;
690	    // 1.Extract
691	    ExtractFp16(v1, sa, ea, maTmp);
692	    ExtractFp16(v2, sb, eb, mbTmp);
693	    uint32_t ma = maTmp;
694	    uint32_t mb = mbTmp;
695	
696	    int16_t eRet =
697	        (ea + eb - static_cast<uint16_t>(Fp16BasicParam::K_FP16_EXP_BIAS)) - static_cast<uint16_t>(DimIndex::K_DIM10);
698	    uint32_t mulM = ma * mb;
699	    uint16_t sRet = sa ^ sb;
700	
701	    uint32_t mMin = static_cast<uint16_t>(Fp16BasicParam::K_FP16_MAN_HIDE_BIT);
702	    uint32_t mMax = mMin << 1;
703	    uint32_t mTrunc = 0;
704	    // the value of mRet should not be smaller than 2^23
705	    while ((mulM < mMin) && (eRet > 1)) {
706	        mulM = mulM << 1;
707	        eRet = eRet - 1;
708	    }
709	    while ((mulM >= mMax) || (eRet < 1)) {
710	        mTrunc = mTrunc >> 1;
711	        mTrunc = mTrunc | (static_cast<uint32_t>(Fp32BasicParam::K_FP32_SIGN_MASK) * (mulM & 1));
712	        mulM = mulM >> 1;
713	        eRet = eRet + 1;
714	    }
715	    bool bLastBit = ((mulM & 1) > 0);
716	    bool bTruncHigh = (ROUND_MODE == TagFp16RoundMode::K_ROUND_TO_NEAREST) &&
717	                      ((mTrunc & static_cast<uint32_t>(Fp32BasicParam::K_FP32_SIGN_MASK)) > 0);
718	    bool bTruncLeft = (ROUND_MODE == TagFp16RoundMode::K_ROUND_TO_NEAREST) &&
719	                      ((mTrunc & static_cast<uint32_t>(Fp32BasicParam::K_FP32_ABS_MAX)) > 0);
720	    mulM = ManRoundToNearest(bLastBit, bTruncHigh, bTruncLeft, mulM);
721	
722	    while ((mulM >= mMax) || (eRet < 0)) {
723	        mulM = mulM >> 1;
724	        eRet = eRet + 1;
725	    }
726	
727	    if ((eRet == 1) && (mulM < static_cast<uint16_t>(Fp16BasicParam::K_FP16_MAN_HIDE_BIT))) {
728	        eRet = 0;
729	    }
730	    mRet = static_cast<uint16_t>(mulM);
731	
732	    Fp16Normalize(eRet, mRet);
733	
734	    uint16_t ret = FP16_CONSTRUCTOR(sRet, static_cast<uint16_t>(eRet), mRet);
735	    return ret;
736	}
