738	/**
739	 * @ingroup half math operator divided
740	 * @param [in] v1 left operator value of half object
741	 * @param [in] v2 right operator value of half object
742	 * @brief   Performing half division
743	 * @return  Return half result of division this by fp
744	 */
745	static uint16_t Fp16Div(uint16_t v1, uint16_t v2)
746	{
747	    uint16_t ret;
748	    if (FP16_IS_ZERO(v2)) { // result is inf
749	        // throw "half division by zero.";
750	        uint16_t sa;
751	        uint16_t sb;
752	        uint16_t sRet;
753	        sa = FP16_EXTRAC_SIGN(v1);
754	        sb = FP16_EXTRAC_SIGN(v2);
755	        sRet = sa ^ sb;
756	        ret = FP16_CONSTRUCTOR(sRet, static_cast<uint16_t>(Fp16BasicParam::K_FP16_MAX_EXP), 0u);
757	    } else if (FP16_IS_ZERO(v1)) {
758	        ret = 0u;
759	    } else {
760	        uint16_t sa;
761	        uint16_t sb;
762	        int16_t ea;
763	        int16_t eb;
764	        uint16_t maTmp;
765	        uint16_t mbTmp;
766	        // 1.Extract
767	        ExtractFp16(v1, sa, ea, maTmp);
768	        ExtractFp16(v2, sb, eb, mbTmp);
769	        uint64_t ma = maTmp;
770	        uint64_t mb = mbTmp;
771	        uint64_t mTmp;
772	        if (ea > eb) {
773	            mTmp = ma;
774	            int16_t tmp = ea - eb;
775	            for (int16_t i = 0; i < tmp; i++) {
776	                mTmp = mTmp << 1;
777	            }
778	            ma = mTmp;
779	        } else if (ea < eb) {
780	            mTmp = mb;
781	            int16_t tmp = eb - ea;
782	            for (int16_t i = 0; i < tmp; i++) {
783	                mTmp = mTmp << 1;
784	            }
785	            mb = mTmp;
786	        }
787	        float mDiv = static_cast<float>(ma * 1.0f / mb);
788	        half fpDiv(mDiv);
789	        ret = fpDiv.val;
790	        if (sa != sb) {
791	            ret |= static_cast<uint16_t>(Fp16BasicParam::K_FP16_SIGN_MASK);
792	        }
793	    }
794	    return ret;
795	}
