873	static bool CmpPosNums(const uint16_t& ea, const uint16_t& eb, const uint16_t& ma, const uint16_t& mb)
874	{
875	    bool result = true;
876	    if (ea > eb) { // ea - eb >= 1; Va always larger than Vb
877	        result = true;
878	    } else if (ea == eb) {
879	        result = ma > mb;
880	    } else {
881	        result = false;
882	    }
883	    return result;
884	}
885	static bool CmpNegNums(const uint16_t& ea, const uint16_t& eb, const uint16_t& ma, const uint16_t& mb)
886	{
887	    bool result = true;
888	    if (ea < eb) {
889	        result = true;
890	    } else if (ea == eb) {
891	        result = ma < mb;
892	    } else {
893	        result = false;
894	    }
895	    return result;
896	}
897	bool half::operator>(const half& fp) const
898	{
899	    uint16_t sa;
900	    uint16_t sb;
901	    uint16_t ea;
902	    uint16_t eb;
903	    uint16_t ma;
904	    uint16_t mb;
905	    bool result = true;
906	
907	    // 1.Extract
908	    sa = FP16_EXTRAC_SIGN(val);
909	    sb = FP16_EXTRAC_SIGN(fp.val);
910	    ea = static_cast<uint16_t>(FP16_EXTRAC_EXP(val));
911	    eb = static_cast<uint16_t>(FP16_EXTRAC_EXP(fp.val));
912	    ma = FP16_EXTRAC_MAN(val);
913	    mb = FP16_EXTRAC_MAN(fp.val);
914	
915	    // Compare
916	    if ((sa == 0) && (sb > 0)) { // +  -
917	        // -0=0
918	        result = !(FP16_IS_ZERO(val) && FP16_IS_ZERO(fp.val));
919	    } else if ((sa == 0) && (sb == 0)) { // + +
920	        result = CmpPosNums(ea, eb, ma, mb);
921	    } else if ((sa > 0) && (sb > 0)) { // - -    opposite to  + +
922	        result = CmpNegNums(ea, eb, ma, mb);
923	    } else {
924	        // -  +
925	        result = false;
926	    }
927	
928	    return result;
929	}
