993	uint16_t half::FloatToFp16(const float& fVal) const
994	{
995	    uint16_t sRet;
996	    uint16_t mRet;
997	    int16_t eRet;
998	    uint32_t ef;
999	    uint32_t mf;
1000	    const uint32_t ui32V = *(reinterpret_cast<const uint32_t*>(&fVal)); // 1:8:23bit sign:exp:man
1001	    uint32_t mLenDelta;
1002	
1003	    sRet = static_cast<uint16_t>(
1004	        (ui32V & static_cast<uint32_t>(Fp32BasicParam::K_FP32_SIGN_MASK)) >>
1005	        static_cast<uint16_t>(Fp32BasicParam::K_FP32_SIGN_INDEX)); // 4Byte->2Byte
1006	    ef = (ui32V & static_cast<uint32_t>(Fp32BasicParam::K_FP32_EXP_MASK)) >>
1007	         static_cast<uint16_t>(Fp32BasicParam::K_FP32_MAN_LEN); // 8 bit exponent
1008	    mf =
1009	        (ui32V &
1010	         static_cast<uint32_t>(Fp32BasicParam::K_FP32_MAN_MASK)); // 23 bit mantissa dont't need to care about denormal
1011	    mLenDelta =
1012	        static_cast<uint16_t>(Fp32BasicParam::K_FP32_MAN_LEN) - static_cast<uint16_t>(Fp16BasicParam::K_FP16_MAN_LEN);
1013	
1014	    bool needRound = false;
1015	    // Exponent overflow/NaN converts to signed inf/NaN
1016	    if (ef > 0x8Fu) { // 0x8Fu:142=127+15
1017	        eRet = static_cast<uint16_t>(Fp16BasicParam::K_FP16_MAX_EXP) - 1;
1018	        mRet = static_cast<uint16_t>(Fp16BasicParam::K_FP16_MAX_MAN);
1019	    } else if (ef <= 0x70u) { // 0x70u:112=127-15 Exponent underflow converts to denormalized half or signed zero
1020	        eRet = 0;
1021	        if (ef >= 0x67) { // 0x67:103=127-24 Denormal
1022	            mf = (mf | static_cast<uint32_t>(Fp32BasicParam::K_FP32_MAN_HIDE_BIT));
1023	            uint16_t shiftOut = static_cast<uint16_t>(Fp32BasicParam::K_FP32_MAN_LEN);
1024	            uint64_t mTmp = (static_cast<uint64_t>(mf)) << (ef - 0x67);
1025	
1026	            needRound = IsRoundOne(mTmp, shiftOut);
1027	            mRet = static_cast<uint16_t>(mTmp >> shiftOut);
1028	            if (needRound) {
1029	                mRet++;
1030	            }
1031	        } else if ((ef == 0x66) && (mf > 0)) { // 0x66:102 Denormal 0<f_v<min(Denormal)
1032	            mRet = 1;
1033	        } else {
1034	            mRet = 0;
1035	        }
1036	    } else { // Regular case with no overflow or underflow
1037	        eRet = static_cast<int16_t>(ef - 0x70u);
1038	
1039	        needRound = IsRoundOne(mf, static_cast<uint16_t>(mLenDelta));
1040	        mRet = static_cast<uint16_t>(mf >> mLenDelta);
1041	        if (needRound) {
1042	            mRet++;
1043	        }
1044	        if ((mRet & static_cast<uint16_t>(Fp16BasicParam::K_FP16_MAN_HIDE_BIT)) != 0) {
1045	            eRet++;
1046	        }
1047	    }
1048	
1049	    Fp16Normalize(eRet, mRet);
1050	    return FP16_CONSTRUCTOR(sRet, static_cast<uint16_t>(eRet), mRet);
1051	}
