1053	uint16_t half::DoubleToFp16(const double& dVal)
1054	{
1055	    uint16_t sRet;
1056	    uint16_t mRet;
1057	    int16_t eRet;
1058	    uint64_t ed;
1059	    uint64_t md;
1060	    uint64_t ui64V = *(reinterpret_cast<const uint64_t*>(&dVal)); // 1:11:52bit sign:exp:man
1061	    uint16_t mLenDelta;
1062	
1063	    sRet = static_cast<uint16_t>(
1064	        (ui64V & static_cast<uint64_t>(Fp64BasicParam::K_FP64_SIGN_MASK)) >>
1065	        static_cast<uint16_t>(Fp64BasicParam::K_FP64_SIGN_INDEX)); // 4Byte
1066	    ed = (ui64V & static_cast<uint64_t>(Fp64BasicParam::K_FP64_EXP_MASK)) >>
1067	         static_cast<uint16_t>(Fp64BasicParam::K_FP64_MAN_LEN);            // 10 bit exponent
1068	    md = (ui64V & static_cast<uint64_t>(Fp64BasicParam::K_FP64_MAN_MASK)); // 52 bit mantissa
1069	    mLenDelta =
1070	        static_cast<uint16_t>(Fp64BasicParam::K_FP64_MAN_LEN) - static_cast<uint16_t>(Fp16BasicParam::K_FP16_MAN_LEN);
1071	
1072	    bool needRound = false;
1073	    // Exponent overflow/NaN converts to signed inf/NaN
1074	    if (ed >= 0x410u) { // 0x410:1040=1023+16
1075	        eRet = static_cast<uint16_t>(Fp16BasicParam::K_FP16_MAX_EXP) - 1;
1076	        mRet = static_cast<uint16_t>(Fp16BasicParam::K_FP16_MAX_MAN);
1077	        val = FP16_CONSTRUCTOR(sRet, static_cast<uint16_t>(eRet), mRet);
1078	    } else if (ed <= 0x3F0u) { // Exponent underflow converts to denormalized half or signed zero
1079	        // 0x3F0:1008=1023-15
1080	        // Signed zeros, denormalized floats, and floats with small
1081	        // exponents all convert to signed zero half precision.
1082	        eRet = 0;
1083	        if (ed >= 0x3E7u) { // 0x3E7u:999=1023-24 Denormal
1084	            // Underflows to a denormalized value
1085	            md = (static_cast<uint64_t>(Fp64BasicParam::K_FP64_MAN_HIDE_BIT) | md);
1086	            uint16_t shiftOut = static_cast<uint16_t>(Fp64BasicParam::K_FP64_MAN_LEN);
1087	            uint64_t mTmp = (static_cast<uint64_t>(md)) << (ed - 0x3E7u);
1088	
1089	            needRound = IsRoundOne(mTmp, shiftOut);
1090	            mRet = static_cast<uint16_t>(mTmp >> shiftOut);
1091	            if (needRound) {
1092	                mRet++;
1093	            }
1094	        } else if ((ed == 0x3E6u) && (md > 0)) {
1095	            mRet = 1;
1096	        } else {
1097	            mRet = 0;
1098	        }
1099	    } else { // Regular case with no overflow or underflow
1100	        eRet = static_cast<int16_t>(ed - 0x3F0u);
1101	
1102	        needRound = IsRoundOne(md, mLenDelta);
1103	        mRet = static_cast<uint16_t>(md >> mLenDelta);
1104	        if (needRound) {
1105	            mRet++;
1106	        }
1107	        if ((static_cast<uint16_t>(Fp16BasicParam::K_FP16_MAN_HIDE_BIT) & mRet) != 0) {
1108	            eRet++;
1109	        }
1110	    }
1111	
1112	    Fp16Normalize(eRet, mRet);
1113	    return FP16_CONSTRUCTOR(sRet, static_cast<uint16_t>(eRet), mRet);
1114	}
