1161	static void SetValByUint16Val(const uint16_t& inputVal, const uint16_t& sign, uint16_t& retVal)
1162	{
1163	    uint32_t mTmp = (inputVal & static_cast<uint32_t>(Fp32BasicParam::K_FP32_ABS_MAX));
1164	    uint16_t mMin = static_cast<uint16_t>(Fp16BasicParam::K_FP16_MAN_HIDE_BIT);
1165	    uint16_t mMax = mMin << 1;
1166	    uint16_t len = static_cast<uint16_t>(GetManBitLength(mTmp));
1167	    if (mTmp != 0) {
1168	        uint16_t eRet;
1169	        if (len > static_cast<uint16_t>(DimIndex::K_DIM11)) {
1170	            eRet = static_cast<uint16_t>(Fp16BasicParam::K_FP16_EXP_BIAS) +
1171	                   static_cast<uint16_t>(Fp16BasicParam::K_FP16_MAN_LEN);
1172	            uint32_t eTmp = static_cast<uint32_t>(len) - static_cast<uint32_t>(DimIndex::K_DIM11);
1173	            uint32_t truncMask = 1;
1174	            for (uint32_t i = 1; i < eTmp; i++) {
1175	                truncMask = (truncMask << 1) + 1;
1176	            }
1177	            uint32_t mTrunc = (mTmp & truncMask) << (static_cast<uint32_t>(BitShift::K_BIT_SHIFT32) - eTmp);
1178	            for (uint32_t i = 0; i < eTmp; i++) {
1179	                eRet = eRet + 1;
1180	                mTmp = (mTmp >> 1);
1181	            }
1182	            bool bLastBit = ((mTmp & 1) > 0);
1183	            bool bTruncHigh = static_cast<bool>(0);
1184	            bool bTruncLeft = static_cast<bool>(0);
1185	            if (ROUND_MODE == TagFp16RoundMode::K_ROUND_TO_NEAREST) { // trunc
1186	                bTruncHigh = ((mTrunc & static_cast<uint32_t>(Fp32BasicParam::K_FP32_SIGN_MASK)) > 0);
1187	                bTruncLeft = ((mTrunc & static_cast<uint32_t>(Fp32BasicParam::K_FP32_ABS_MAX)) > 0);
1188	            }
1189	            mTmp = ManRoundToNearest(bLastBit, bTruncHigh, bTruncLeft, mTmp);
1190	            while (mTmp >= mMax) {
1191	                mTmp = mTmp >> 1;
1192	                eRet = eRet + 1;
1193	            }
1194	        } else {
1195	            eRet = static_cast<uint16_t>(Fp16BasicParam::K_FP16_EXP_BIAS);
1196	            mTmp = mTmp << static_cast<uint32_t>(K_MAN_BIT_LENGTH - len);
1197	            eRet = eRet + (len - static_cast<uint16_t>(1));
1198	        }
1199	        auto mRet = static_cast<uint16_t>(mTmp);
1200	        retVal = FP16_CONSTRUCTOR(sign, eRet, mRet);
1201	    }
1202	}
