1339	                   static_cast<uint16_t>(Fp16BasicParam::K_FP16_MAN_LEN);
1340	            uint32_t truncMask = 1;
1341	            uint16_t eTmp = len - static_cast<uint16_t>(DimIndex::K_DIM11);
1342	            for (uint16_t i = 1; i < eTmp; i++) {
1343	                truncMask = (truncMask << 1) + 1;
1344	            }
1345	            uint32_t mTrunc = (mTmp & truncMask)
1346	                              << static_cast<uint32_t>(static_cast<uint16_t>(BitShift::K_BIT_SHIFT32) - eTmp);
1347	            for (uint16_t i = 0; i < eTmp; i++) {
1348	                mTmp = (mTmp >> 1);
1349	                eRet = eRet + 1;
1350	            }
1351	            bool bLastBit = ((mTmp & 1) > 0);
1352	            bool bTruncHigh = false;
1353	            bool bTruncLeft = false;
1354	            if (ROUND_MODE == TagFp16RoundMode::K_ROUND_TO_NEAREST) { // trunc
1355	                bTruncHigh = ((mTrunc & static_cast<uint32_t>(Fp32BasicParam::K_FP32_SIGN_MASK)) > 0);
1356	                bTruncLeft = ((mTrunc & static_cast<uint32_t>(Fp32BasicParam::K_FP32_ABS_MAX)) > 0);
1357	            }
1358	            mTmp = ManRoundToNearest(bLastBit, bTruncHigh, bTruncLeft, mTmp);
1359	            while (mTmp >= mMax) {
1360	                mTmp = mTmp >> 1;
1361	                eRet = eRet + 1;
1362	            }
1363	            if (eRet >= static_cast<uint16_t>(Fp16BasicParam::K_FP16_MAX_EXP)) {
1364	                eRet = static_cast<uint16_t>(Fp16BasicParam::K_FP16_MAX_EXP) - 1;
1365	                mTmp = static_cast<uint16_t>(Fp16BasicParam::K_FP16_MAX_MAN);
1366	            }
1367	        } else {
1368	            eRet = static_cast<uint16_t>(Fp16BasicParam::K_FP16_EXP_BIAS);
1369	            mTmp = mTmp << (static_cast<uint32_t>(DimIndex::K_DIM11) - static_cast<uint32_t>(len));
1370	            eRet = eRet + (len - static_cast<uint16_t>(1));
1371	        }
1372	        auto mRet = static_cast<uint16_t>(mTmp);
1373	        return FP16_CONSTRUCTOR(0u, eRet, mRet);
1374	    }
1375	}
